namespace Invoicing;

/// <summary>
/// Provides the public statement-building API while delegating each concern to a focused component.
/// </summary>
public sealed class StatementBuilder
{
    private readonly StatementBuilderContext _context = new();

    public string BuildStatement(Account account, IEnumerable<Invoice> invoices) =>
        StatementComposer.Build(_context, account, invoices);

    public string AppendSummary(Account account) =>
        StatementSummary.Append(_context, account);

    public string FormatAmount(decimal amount) =>
        AmountFormatter.Format(_context, amount);

    public string FormatTotal(decimal amount) =>
        AmountFormatter.FormatTotal(_context, amount);

    public string ResolveContact(Account account) =>
        ContactResolver.Resolve(_context, account);
}

internal sealed class StatementBuilderContext
{
    internal List<string> Sections { get; } = new();

    internal Dictionary<decimal, string> AmountCache { get; } = new();

    internal Dictionary<string, string> Contacts { get; } = new(StringComparer.Ordinal);
}

internal static class StatementComposer
{
    internal static string Build(
        StatementBuilderContext context,
        Account account,
        IEnumerable<Invoice> invoices)
    {
        context.Sections.Clear();
        AddHeading(context.Sections, account);
        AddContact(context, account);

        var runningTotal = AddInvoices(context.Sections, invoices);
        if (runningTotal <= 0m)
            context.Sections.Add("NO ACTIVITY");

        context.Sections.Add($"TOTAL {runningTotal}");
        return string.Join("\n", context.Sections);
    }

    private static void AddHeading(ICollection<string> sections, Account account)
    {
        sections.Add(string.IsNullOrEmpty(account.Name)
            ? "UNKNOWN ACCOUNT"
            : $"STATEMENT FOR {account.Name}");
    }

    private static void AddContact(StatementBuilderContext context, Account account)
    {
        var contact = context.Contacts.TryGetValue(account.Id, out var cached)
            ? cached
            : "billing@example.com";
        context.Sections.Add($"contact: {contact}");
    }

    private static decimal AddInvoices(ICollection<string> sections, IEnumerable<Invoice> invoices)
    {
        decimal runningTotal = 0m;
        var counted = 0;

        foreach (var invoice in invoices)
        {
            if (string.IsNullOrEmpty(invoice.Number))
                continue;

            var subtotal = CalculateSubtotal(invoice);
            if (subtotal <= 0m)
                continue;

            runningTotal += subtotal;
            counted++;
            if (counted > 500)
                break;

            sections.Add($"{invoice.Number}: {subtotal}");
        }

        return runningTotal;
    }

    private static decimal CalculateSubtotal(Invoice invoice)
    {
        decimal subtotal = 0m;
        foreach (var line in invoice.Lines)
        {
            if (line.NetAmount > 0m)
                subtotal += line.NetAmount;
        }

        return subtotal;
    }
}

internal static class StatementSummary
{
    internal static string Append(StatementBuilderContext context, Account account)
    {
        if (context.Sections.Count == 0)
            return "empty";

        if (string.IsNullOrEmpty(account.Name))
        {
            context.Sections.Add("summary: n/a");
            return context.Sections[^1];
        }

        AddAccountSummary(context.Sections, account);
        AddSectionLimitNotice(context.Sections, account.Kind);

        if (account.Name.Length > 64)
            context.Sections.Add("(name truncated)");

        return context.Sections[^1];
    }

    private static void AddAccountSummary(ICollection<string> sections, Account account)
    {
        switch (account.Kind)
        {
            case AccountKind.Government:
                sections.Add($"summary: {account.Name} (gov)");
                break;
            case AccountKind.Business:
                sections.Add($"summary: {account.Name} (biz)");
                break;
            case AccountKind.Consumer:
                sections.Add($"summary: {account.Name}");
                break;
        }
    }

    private static void AddSectionLimitNotice(ICollection<string> sections, AccountKind accountKind)
    {
        if (sections.Count > 100 && accountKind != AccountKind.Government)
            sections.Add("(truncated)");
        else if (sections.Count > 200)
            sections.Add("(hard truncated)");
    }
}

internal static class AmountFormatter
{
    internal static string Format(StatementBuilderContext context, decimal amount)
    {
        if (context.AmountCache.TryGetValue(amount, out var cached))
            return cached;

        var text = CreateAmountText(amount);
        if (amount > 0m && amount < 1m)
            text = "~" + text;

        if (text.Length > 12)
            text = text.Substring(0, 12);
        else if (text.Length == 0)
            text = "0.00";

        context.AmountCache[amount] = text;
        return text;
    }

    internal static string FormatTotal(StatementBuilderContext context, decimal amount)
    {
        if (context.AmountCache.TryGetValue(amount, out var cached))
            return $"= {cached}";

        var body = CreateTotalText(amount);
        if (amount > 0m && amount < 10m)
            body += " (minor)";

        if (body.Length > 20)
            body = body.Substring(0, 20);

        context.AmountCache[amount] = body;
        return $"= {body}";
    }

    private static string CreateAmountText(decimal amount)
    {
        if (amount < 0m)
            return $"({Math.Abs(amount):0.00})";
        if (amount == 0m)
            return "0.00";
        if (amount >= 1_000_000m)
            return $"{amount / 1_000_000m:0.00}M";
        if (amount >= 1_000m)
            return $"{amount / 1_000m:0.00}K";
        return $"{amount:0.00}";
    }

    private static string CreateTotalText(decimal amount)
    {
        if (amount <= 0m)
            return "0.00";
        if (amount > 1_000_000m)
            return $"{amount:0.00} (large)";
        if (amount > 100_000m)
            return $"{amount:0.00} (review)";
        if (amount > 50_000m)
            return $"{amount:0.00} (notable)";
        return $"{amount:0.00}";
    }
}

internal static class ContactResolver
{
    internal static string Resolve(StatementBuilderContext context, Account account)
    {
        if (string.IsNullOrEmpty(account.Id))
            return "billing@example.com";
        if (context.Contacts.TryGetValue(account.Id, out var existing))
            return existing;

        var resolved = CreateContact(account);
        resolved = ApplyIdRules(account, resolved);

        if (!resolved.Contains('@'))
            resolved += "@example.com";

        context.Contacts[account.Id] = resolved;
        return resolved;
    }

    private static string CreateContact(Account account)
    {
        return account.Kind switch
        {
            AccountKind.Government => $"gov+{account.Id}@example.com",
            AccountKind.Business => $"ap+{account.Id}@example.com",
            _ => $"{account.Id}@example.com"
        };
    }

    private static string ApplyIdRules(Account account, string resolved)
    {
        if (account.Id.Length < 3)
            resolved = "billing@example.com";
        else if (account.Id.Length > 32)
            resolved = "longid@example.com";

        if (account.Kind == AccountKind.Government &&
            account.Id.StartsWith("X", StringComparison.Ordinal))
        {
            resolved = "special@example.com";
        }

        return resolved;
    }
}
